package com.project.entity.enterprise;
import com.project.entity.Employee; import javax.persistence.*; import java.time.LocalDate;
@Entity @Table(name="performance_goals") public class PerformanceGoal { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(fetch=FetchType.EAGER) @JoinColumn(name="employee_id",nullable=false) private Employee employee; private String goalType="KPI"; private String title; @Column(length=1000) private String description; private int targetPercent=100; private int progressPercent=0; private String status="OPEN"; private LocalDate dueDate; public Long getId(){return id;} public Employee getEmployee(){return employee;} public void setEmployee(Employee v){employee=v;} public String getGoalType(){return goalType;} public void setGoalType(String v){goalType=v;} public String getTitle(){return title;} public void setTitle(String v){title=v;} public String getDescription(){return description;} public void setDescription(String v){description=v;} public int getTargetPercent(){return targetPercent;} public void setTargetPercent(int v){targetPercent=v;} public int getProgressPercent(){return progressPercent;} public void setProgressPercent(int v){progressPercent=v;} public String getStatus(){return status;} public void setStatus(String v){status=v;} public LocalDate getDueDate(){return dueDate;} public void setDueDate(LocalDate v){dueDate=v;} }
